import React, { useState, useEffect } from 'react';
import { motion } from 'framer-motion';

// Generate a random number between min and max
const random = (min, max) => Math.random() * (max - min) + min;

// Generate random confetti pieces
const generateConfetti = (count = 50) => {
  return Array.from({ length: count }).map((_, i) => {
    const colors = [
      '#3B82F6', // blue-500
      '#10B981', // green-500
      '#F59E0B', // amber-500
      '#EF4444', // red-500
      '#8B5CF6', // purple-500
      '#EC4899', // pink-500
      '#06B6D4', // cyan-500
    ];
    
    const shapes = ['circle', 'square', 'triangle', 'line'];
    
    return {
      id: i,
      x: random(0, 100), // Random starting X position (percentage)
      y: random(-20, -5), // Start above the container
      size: random(5, 15), // Random size
      rotation: random(0, 360), // Random rotation
      color: colors[Math.floor(random(0, colors.length))], // Random color
      shape: shapes[Math.floor(random(0, shapes.length))], // Random shape
      xVelocity: random(-2, 2), // X direction movement
      yVelocity: random(2, 5), // Y direction movement (falling speed)
      rotationVelocity: random(-2, 2), // Rotation speed
    };
  });
};

const ConfettiPiece = ({ piece }) => {
  if (piece.shape === 'circle') {
    return (
      <motion.div
        className="absolute rounded-full"
        style={{
          width: piece.size,
          height: piece.size,
          backgroundColor: piece.color,
          top: `${piece.y}%`,
          left: `${piece.x}%`,
          opacity: 0.8,
        }}
        animate={{
          y: ['0%', '120%'],
          x: [`${piece.x}%`, `${piece.x + piece.xVelocity * 20}%`],
          rotate: [0, piece.rotation + piece.rotationVelocity * 360],
          opacity: [0.8, 0],
        }}
        transition={{
          duration: 2 + random(-0.5, 1),
          ease: 'easeOut',
        }}
      />
    );
  }
  
  if (piece.shape === 'square') {
    return (
      <motion.div
        className="absolute"
        style={{
          width: piece.size,
          height: piece.size,
          backgroundColor: piece.color,
          top: `${piece.y}%`,
          left: `${piece.x}%`,
          opacity: 0.8,
        }}
        animate={{
          y: ['0%', '120%'],
          x: [`${piece.x}%`, `${piece.x + piece.xVelocity * 20}%`],
          rotate: [0, piece.rotation + piece.rotationVelocity * 360],
          opacity: [0.8, 0],
        }}
        transition={{
          duration: 2 + random(-0.5, 1),
          ease: 'easeOut',
        }}
      />
    );
  }
  
  if (piece.shape === 'triangle') {
    return (
      <motion.div
        className="absolute"
        style={{
          width: 0,
          height: 0,
          borderLeft: `${piece.size / 2}px solid transparent`,
          borderRight: `${piece.size / 2}px solid transparent`,
          borderBottom: `${piece.size}px solid ${piece.color}`,
          top: `${piece.y}%`,
          left: `${piece.x}%`,
          opacity: 0.8,
        }}
        animate={{
          y: ['0%', '120%'],
          x: [`${piece.x}%`, `${piece.x + piece.xVelocity * 20}%`],
          rotate: [0, piece.rotation + piece.rotationVelocity * 360],
          opacity: [0.8, 0],
        }}
        transition={{
          duration: 2 + random(-0.5, 1),
          ease: 'easeOut',
        }}
      />
    );
  }
  
  // Line shape
  return (
    <motion.div
      className="absolute"
      style={{
        width: piece.size * 2,
        height: piece.size / 4,
        backgroundColor: piece.color,
        top: `${piece.y}%`,
        left: `${piece.x}%`,
        opacity: 0.8,
      }}
      animate={{
        y: ['0%', '120%'],
        x: [`${piece.x}%`, `${piece.x + piece.xVelocity * 20}%`],
        rotate: [0, piece.rotation + piece.rotationVelocity * 360],
        opacity: [0.8, 0],
      }}
      transition={{
        duration: 2 + random(-0.5, 1),
        ease: 'easeOut',
      }}
    />
  );
};

const Confetti = ({ count = 50, duration = 2000 }) => {
  const [pieces, setPieces] = useState([]);
  
  useEffect(() => {
    // Generate confetti pieces when component mounts
    setPieces(generateConfetti(count));
    
    // Clean up after duration
    const timer = setTimeout(() => {
      setPieces([]);
    }, duration);
    
    return () => clearTimeout(timer);
  }, [count, duration]);
  
  return (
    <div className="absolute inset-0 overflow-hidden pointer-events-none z-10">
      {pieces.map((piece) => (
        <ConfettiPiece key={piece.id} piece={piece} />
      ))}
    </div>
  );
};

export default Confetti; 